refentry.refsect1:
&reftitle.parameters;




   connection

    &pgsql.parameter.connection-with-unspecified-default;



   string



     Una string contenente testo o dati binari da inserire in una colonna
     bytea.

  &reftitle.examples;



    Esempio di pg_escape_bytea


<?php 
  // Connessione al database
  $dbconn = pg_connect('dbname=foo');

  // Lettura di un file binario
  $data = file_get_contents('image1.jpg');

  // Escape dei dati binari
  $escaped = pg_escape_bytea($data);

  // Inserimento nel database
  pg_query("INSERT INTO gallery (name, data) VALUES ('Pini', '{$escaped}')");
?>
